using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00010 : ControllerTestBase
    {
        [TestMethod]
        public void Response_Type_Does_Not_Contain_Multiple_Generic_Types()
        {
            var invalidResponseTypes = (from controller in Controllers
                                        from method in controller.Methods
                                        where method.ReturnParameter.Count(c => c == '>') > 1
                                        select new
                                        {
                                            ErrorClass = controller.FullQualifiedName,
                                            Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
MethodName: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:     

// Please replace the 'Response' with the correct response type you want to return.
{method.MethodValue.Replace(method.ReturnParameter, "Task<Response>").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                        }).ToImmutableList();

            Assert.IsTrue(invalidResponseTypes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00010

Missing produce response type for Error result. Findings {invalidResponseTypes.Count}': {Environment.NewLine}{invalidResponseTypes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
